"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["51089"],{57513(e){e.exports=JSON.parse('{"id":"FIN-666","slug":"cost-synergy","term":"Cost Synergy","also_known_as":[],"difficulty":"Intermediate","definition":"A cost synergy is a saving that two businesses expect to achieve by combining, through eliminating duplicate costs, gaining scale or operating more efficiently together.","explanation":["When companies merge, they often perform many of the same activities. Combining them can remove duplication and reduce costs.","Common sources of cost synergies include merging head offices and support functions, such as finance, legal and human resources; closing overlapping branches, factories or warehouses; combining purchasing to negotiate lower prices from suppliers; consolidating IT systems; and reducing overlapping marketing or sales teams.","For example, two banks that merge might expect to save 200 million a year by closing branches in the same towns and combining their technology platforms.","Cost synergies are generally considered more achievable than revenue synergies, because companies have more control over their own costs than over customer behaviour. Even so, they often take several years to realize fully, and achieving them usually involves one-off integration costs, such as redundancy payments and system migration expenses.","Analysts assess the credibility of announced cost synergies by examining the overlap between the businesses, the timetable and the expected integration costs. Overestimating synergies is a common reason acquisitions fail to deliver value."],"note":"","total":1500,"prev":{"slug":"cost-push-inflation","term":"Cost-Push Inflation"},"next":{"slug":"counterparty-risk","term":"Counterparty Risk"}}')}}]);